import Database from 'better-sqlite3';

const dbPath = '/home/user/qwik-app/poll.db';

export const db = new Database(dbPath, { timeout: 5000 });
db.pragma('journal_mode = WAL');
db.pragma('synchronous = NORMAL');

export interface Poll {
  id: string;
  question: string;
}

export interface Option {
  id: number;
  poll_id: string;
  text: string;
  votes: number;
}

export interface VoteLog {
  id: number;
  poll_id: string;
  ip: string;
  timestamp: number;
}

export function getPollWithOptions(pollId: string): { poll: Poll; options: Option[] } | null {
  try {
    const poll = db.prepare('SELECT * FROM polls WHERE id = ?').get(pollId) as Poll | undefined;
    if (!poll) {
      return null;
    }
    const options = db.prepare('SELECT * FROM options WHERE poll_id = ?').all(pollId) as Option[];
    return { poll, options };
  } catch (err) {
    console.error('Error fetching poll with options:', err);
    return null;
  }
}

export function castVote(
  pollId: string,
  optionId: number,
  ip: string
): { success: boolean; error?: string; status?: number; votes?: Record<string, number> } {
  const now = Date.now();
  const fiveSecondsAgo = now - 5000;

  try {
    const transaction = db.transaction(() => {
      // 1. Check if poll exists
      const poll = db.prepare('SELECT id FROM polls WHERE id = ?').get(pollId);
      if (!poll) {
        return { success: false, error: 'Poll or option not found', status: 404 };
      }

      // 2. Check if option exists and belongs to the poll
      const option = db.prepare('SELECT id FROM options WHERE id = ? AND poll_id = ?').get(optionId, pollId);
      if (!option) {
        return { success: false, error: 'Poll or option not found', status: 404 };
      }

      // 3. Check rate limit
      const recentVote = db.prepare(
        'SELECT id FROM votes_log WHERE poll_id = ? AND ip = ? AND timestamp > ? LIMIT 1'
      ).get(pollId, ip, fiveSecondsAgo);

      if (recentVote) {
        return { success: false, error: 'Rate limit exceeded', status: 429 };
      }

      // 4. Log the vote
      db.prepare('INSERT INTO votes_log (poll_id, ip, timestamp) VALUES (?, ?, ?)').run(pollId, ip, now);

      // 5. Increment vote count
      db.prepare('UPDATE options SET votes = votes + 1 WHERE id = ? AND poll_id = ?').run(optionId, pollId);

      // 6. Fetch all options for this poll to return updated votes
      const options = db.prepare('SELECT id, votes FROM options WHERE poll_id = ?').all(pollId) as { id: number; votes: number }[];
      const votes: Record<string, number> = {};
      for (const opt of options) {
        votes[String(opt.id)] = opt.votes;
      }

      return { success: true, votes };
    });

    return transaction();
  } catch (err: any) {
    console.error('Database transaction error:', err);
    return { success: false, error: 'Internal server error', status: 500 };
  }
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { castVote } from "../../../../db";

export const onPost: RequestHandler = async (ev) => {
  const pollId = ev.params.id;

  let body: any;
  try {
    body = await ev.parseBody();
  } catch (err) {
    ev.status(400);
    ev.json(400, { error: "Invalid option ID" });
    return;
  }

  if (!body || typeof body !== "object" || typeof body.optionId !== "number" || isNaN(body.optionId)) {
    ev.status(400);
    ev.json(400, { error: "Invalid option ID" });
    return;
  }

  const optionId = body.optionId;

  // Extract IP address from X-Forwarded-For or fall back to connection socket IP
  let ip = ev.request.headers.get("x-forwarded-for");
  if (ip) {
    ip = ip.split(",")[0].trim();
  } else {
    ip = ev.clientConn.ip || "127.0.0.1";
  }

  const result = castVote(pollId, optionId, ip);

  if (!result.success) {
    const statusCode = result.status || 500;
    ev.status(statusCode);
    ev.json(statusCode, { error: result.error });
    return;
  }

  ev.status(200);
  ev.json(200, {
    success: true,
    votes: result.votes,
  });
};

import { component$, useStore, $ } from "@builder.io/qwik";
import { routeLoader$ } from "@builder.io/qwik-city";
import { getPollWithOptions } from "../../../db";

export const usePollLoader = routeLoader$(async (ev) => {
  const pollId = ev.params.id;
  const pollData = getPollWithOptions(pollId);
  if (!pollData) {
    throw ev.error(404, "Poll not found");
  }
  return pollData;
});

export default component$(() => {
  const loader = usePollLoader();

  const state = useStore({
    options: loader.value.options,
    error: "",
  });

  const handleVote = $(async (optionId: number) => {
    state.error = "";
    try {
      const response = await fetch(`/poll/${loader.value.poll.id}/vote`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ optionId }),
      });

      const data = await response.json();
      if (!response.ok) {
        state.error = data.error || "An error occurred";
        return;
      }

      if (data.success && data.votes) {
        state.options = state.options.map((opt) => ({
          ...opt,
          votes: data.votes[String(opt.id)] ?? opt.votes,
        }));
      }
    } catch (err) {
      state.error = "Failed to submit vote";
    }
  });

  const totalVotes = state.options.reduce((sum, opt) => sum + opt.votes, 0);

  return (
    <div class="poll-container" style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1 id="poll-question">{loader.value.poll.question}</h1>

      {state.error && (
        <div class="error-message" style={{ color: "red", marginBottom: "15px", fontWeight: "bold" }}>
          {state.error}
        </div>
      )}

      <svg id="poll-chart" width="500" height="300" style={{ border: "1px solid #ccc", background: "#f9f9f9" }}>
        {state.options.map((opt, index) => {
          const percentage = totalVotes > 0 ? (opt.votes / totalVotes) : 0;
          const barWidth = percentage * 400;
          const y = 30 + index * 50;

          return (
            <g key={opt.id}>
              <text x="10" y={y + 18} font-size="14" fill="#333">
                {opt.text}
              </text>
              <rect
                class="chart-bar"
                data-option-id={opt.id}
                x="100"
                y={y}
                width={barWidth}
                height="24"
                fill="#3182ce"
                rx="4"
              />
              <text
                class="vote-count"
                data-option-id={opt.id}
                x={110 + barWidth}
                y={y + 18}
                font-size="14"
                fill="#333"
                font-weight="bold"
              >
                {opt.votes}
              </text>
            </g>
          );
        })}
      </svg>

      <div class="vote-buttons" style={{ marginTop: "20px" }}>
        {state.options.map((opt) => (
          <button
            key={opt.id}
            class="vote-button"
            data-option-id={opt.id}
            onClick$={() => handleVote(opt.id)}
            style={{
              marginRight: "10px",
              padding: "8px 16px",
              background: "#3182ce",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Vote for {opt.text}
          </button>
        ))}
      </div>
    </div>
  );
});

